('wizard_arcane_mage','arcane_bolt','{"id":"arcane_bolt","name":"گلوله آرکین","en":"Arcane Bolt","unlockLevel":1,"type":"single_damage","target":"یک دشمن انتخابی","manaPct":3,"cooldownTurns":0,"chargeGain":1,"damagePct":130,"description":"یک گلوله فشرده از انرژی آرکین به هدف شلیک می‌کند. در صورت اصابت یک شارژ آرکین تولید می‌شود.","upgrades":[{"damagePct":145,"description":"آسیب به ۱۴۵٪ قدرت جادویی افزایش می‌یابد."},{"damagePct":160,"description":"آسیب به ۱۶۰٪ قدرت جادویی افزایش می‌یابد."},{"accuracyBonus":5,"description":"دقت این مهارت ۵ واحد درصد افزایش می‌یابد؛ سرعت پرتاب در نبرد نوبتی اثری ندارد."},{"critBonus":5,"description":"شانس ضربه بحرانی جادویی ۵ واحد درصد افزایش می‌یابد."},{"extraChargeChance":15,"description":"۱۵٪ احتمال دارد پس از اصابت، یک شارژ آرکین اضافه تولید شود."},{"damagePct":210,"defensePenetrationPct":20,"description":"آسیب به ۲۱۰٪ می‌رسد و ۲۰٪ دفاع جادویی هدف نادیده گرفته می‌شود."}]}'::jsonb),
