-- ETRANOM v181 Wizard party skill catalog — part 1/6.
begin;
create table if not exists public.party_battle_skill_catalog (specialization_key text not null,skill_id text not null,skill_data jsonb not null,enabled boolean not null default true,primary key(specialization_key,skill_id));
alter table public.party_battle_skill_catalog enable row level security;
revoke all on public.party_battle_skill_catalog from public,anon,authenticated;
on conflict(specialization_key,skill_id) do update set skill_data=excluded.skill_data,enabled=true;
